SELECT DISTINCT ?supplierName ?country ?priceAmount WHERE {
  {
    SELECT ?product ?priceAmount WHERE {
      ?product <http://ld.company.org/prod-vocab/price> ?price .
      ?price <http://ld.company.org/prod-vocab/amount> ?priceAmount .
      ?product <http://ld.company.org/prod-vocab/hasCategory> <http://ld.company.org/prod-vocab/Hardware> .
    }
    ORDER BY DESC(?priceAmount)
    LIMIT 5
    OFFSET 5
  }
  ?product <http://ld.company.org/prod-vocab/hasSupplier> ?supplier .
  ?supplier <http://ld.company.org/prod-vocab/name> ?supplierName .
  ?supplier <http://ld.company.org/prod-vocab/addressCountry> ?country .
}

SELECT ?deptName (COUNT(?emp) AS ?empCount) WHERE {
  ?emp <http://ld.company.org/prod-vocab/memberOf> ?dept .
  ?dept <http://ld.company.org/prod-vocab/name> ?deptName .
} GROUP BY ?deptName HAVING (COUNT(?emp) > 5)

SELECT DISTINCT ?categoryName ?lightestName ?heaviestName WHERE {
  ?category <http://www.w3.org/2000/01/rdf-schema#label> ?categoryName .

  {
    SELECT ?category (MIN(?weight) AS ?minWeight) (MAX(?weight) AS ?maxWeight) WHERE {
      ?hw <http://ld.company.org/prod-vocab/hasCategory> ?category .
      ?hw <http://ld.company.org/prod-vocab/weight_g> ?weight .
    } GROUP BY ?category
  }

  ?lightest <http://ld.company.org/prod-vocab/hasCategory> ?category .
  ?lightest <http://ld.company.org/prod-vocab/weight_g> ?minWeight .
  ?lightest <http://www.w3.org/2000/01/rdf-schema#label> ?lightestName .

  ?heaviest <http://ld.company.org/prod-vocab/hasCategory> ?category .
  ?heaviest <http://ld.company.org/prod-vocab/weight_g> ?maxWeight .
  ?heaviest <http://www.w3.org/2000/01/rdf-schema#label> ?heaviestName .
}

SELECT ?categoryName ?minProduct ?minWeight ?maxProduct ?maxWeight WHERE {
  {
