      ?product a <http://ld.company.org/prod-vocab/Hardware> .
      ?product <http://ld.company.org/prod-vocab/hasCategory> ?category .
      ?product <http://ld.company.org/prod-vocab/weight_g> ?weight .
    } GROUP BY ?category
  }
  ?minProduct a <http://ld.company.org/prod-vocab/Hardware> .
  ?minProduct <http://ld.company.org/prod-vocab/hasCategory> ?category .
  ?minProduct <http://ld.company.org/prod-vocab/weight_g> ?minWeight .
  ?maxProduct a <http://ld.company.org/prod-vocab/Hardware> .
  ?maxProduct <http://ld.company.org/prod-vocab/hasCategory> ?category .
  ?maxProduct <http://ld.company.org/prod-vocab/weight_g> ?maxWeight .
  ?category <http://ld.company.org/prod-vocab/name> ?categoryName .
}

