SELECT DISTINCT ?manager ?managerName ?sameDeptCount ?totalCount ?percentage WHERE {
  ?manager <http://ld.company.org/prod-vocab/hasDirectReport> ?report .
  ?manager <http://ld.company.org/prod-vocab/label> ?managerName .
  ?manager <http://ld.company.org/prod-vocab/memberOf> ?managerDept .
  ?report <http://ld.company.org/prod-vocab/memberOf> ?reportDept .

  {
    SELECT ?manager (COUNT(?report) AS ?totalCount) WHERE {
      ?manager <http://ld.company.org/prod-vocab/hasDirectReport> ?report .
    } GROUP BY ?manager
  }

  {
    SELECT ?manager (COUNT(?report) AS ?sameDeptCount) WHERE {
      ?manager <http://ld.company.org/prod-vocab/hasDirectReport> ?report .
      ?manager <http://ld.company.org/prod-vocab/memberOf> ?managerDept .
      ?report <http://ld.company.org/prod-vocab/memberOf> ?reportDept .
      FILTER(?managerDept = ?reportDept)
    } GROUP BY ?manager
  }

  BIND(?sameDeptCount / ?totalCount * 100 AS ?percentage)
}

SELECT ?manager ?managerName (COUNT(?report) AS ?totalCount) (SUM(IF(?reportDept = ?managerDept, 1, 0)) AS ?sameDeptCount) ((SUM(IF(?reportDept = ?managerDept, 1, 0)) / COUNT(?report)) * 100 AS ?percentage) WHERE {
  ?manager <http://ld.company.org/prod-vocab/hasDirectReport> ?report .
  ?manager <http://www.w3.org/2000/01/rdf-schema#label> ?managerName .
  ?manager <http://ld.company.org/prod-vocab/memberOf> ?managerDept .
  ?report <http://ld.company.org/prod-vocab/memberOf> ?reportDept .
} GROUP BY ?manager ?managerName ?managerDept

